export const GLOSSARY_SHARD = Object.freeze({"market-order":{"slug":"market-order","cat":"trading","en":"Market order","contentLocale":"ja","term":"成行注文","aka":["成行","マーケット注文","Market order"],"short":"成行注文とは、価格を指定せずに、その時点で板にある最も有利な価格から順に、すぐに売買を成立させる注文方法です。","body":[["成行で買うと板の売り注文を安い順に、成行で売ると買い注文を高い順に消化して約定します。約定の速さが最大の利点で、すぐにポジションを持ちたいときや、",["損切り","stop-loss"],"で確実に手放したいときに使われます。"],["一方で、約定価格は事前に確定しません。板が薄い銘柄や相場が急変している局面では、想定より不利な価格で約定する",["スリッページ","slippage"],"が起こりやすくなります。取引所によっては、成行注文に価格の許容幅を設けて、極端な価格での約定を防ぐ仕組みがあります。"],["手数料の面では、成行注文は板の注文を取る側になるため、通常は「",["テイカー手数料","maker-taker-fees"],"」がかかります。一般にテイカー手数料はメイカー手数料より高めに設定されているため、頻繁に取引するとコストの差が積み重なります。"]],"example":"例えば、10万USDT分のBTCを成行で買い、テイカー手数料が0.1%なら手数料は100 USDTです。さらに平均約定価格が表示価格より0.05%高くなれば、スリッページで50 USDTの追加コストがかかり、合計150 USDTになります。同じ注文を指値で出してメイカー手数料0.02%で約定した場合、手数料は20 USDTで、スリッページも発生しません。","mistakes":["板の厚さを確認せずに、小型銘柄で大きな成行注文を出すこと。","急変時に成行で売買し、表示価格と大きく違う価格で約定すること。","成行注文を繰り返し、テイカー手数料が積み重なっていることに気づかないこと。"],"faq":[{"q":"成行注文と指値注文はどちらがいいですか？","a":"すぐに確実に約定させたいなら成行、価格を優先したいなら指値が向いています。目的に応じて使い分けるのが基本です。"},{"q":"成行注文は必ず全部約定しますか？","a":"板に十分な注文があれば基本的に約定しますが、流動性が極端に少ない場合や、取引所の価格保護の仕組みが働いた場合は、一部しか約定しないこともあります。"}],"title":"成行注文とは？メリットと注意点、指値との違い","description":"成行注文の仕組み、メリットとスリッページのリスク、テイカー手数料、指値注文との使い分けを具体例で解説します。","related":[["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"],["slippage","スリッページ","スリッページとは、注文時に想定していた価格と実際に約定した価格との差のことで、主に成行注文や値動きの激しい局面で発生します。"],["maker-taker-fees","メイカー手数料・テイカー手数料（Maker/Taker）","メイカー手数料・テイカー手数料とは、板に注文を置いて流動性を提供した側（メイカー）と、板の注文を即座に約定させた側（テイカー）で分けて設定される取引手数料のことです。"],["order-book","板（オーダーブック）","板（オーダーブック）とは、取引所に出されている買い注文と売り注文を価格ごとに並べた一覧で、どの価格にどれだけの注文が待っているかを示します。"],["stop-loss","損切り注文（ストップロス）","損切り注文（ストップロス）とは、価格があらかじめ決めた水準に達したときに自動で決済し、損失がそれ以上広がらないようにする注文です。"]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"成行、指値、キャンセル：それぞれ何を解決するのか？"},"coin":null,"tool":null,"cta":true},"arbitrage":{"slug":"arbitrage","cat":"trading","en":"Arbitrage","contentLocale":"ja","term":"アービトラージ（裁定取引）","aka":["裁定取引","アビトラ","arbitrage"],"short":"アービトラージ（裁定取引）とは、同じ資産の価格差が取引所間や市場間で生じたときに、安い方で買って高い方で売り、その差を利益にする取引です。","body":[[["暗号資産","cryptocurrency"],"は世界中の多数の取引所で同時に売買されているため、同じBTCでも取引所によって価格が少しずつ違うことがあります。この差を狙うのが取引所間アービトラージです。そのほか、現物と先物の価格差を利用する方法や、",["無期限先物","perpetual-futures"],"の",["資金調達率（ファンディングレート）","funding-rate"],"を受け取る方法、3つの",["通貨ペア","trading-pair"],"を回す三角裁定などがあります。"],["理屈は単純ですが、実際には価格差の多くがコストで消えます。売買手数料、",["出金手数料","withdrawal-fee"],"、",["ブロックチェーン","blockchain"],"の送金時間、スリッページなどです。送金に数十分かかる間に価格差が縮むこともあります。そのため多くの裁定取引者は、両方の取引所にあらかじめ資金を置いておき、送金を待たずに同時に売買します。"],"価格差が大きく開いているときは、出金停止や入金の遅延、流動性の薄さなど理由があることが多いです。韓国ウォン市場で見られる「キムチプレミアム」のように、資本規制などで差が長く続く例もあります。"],"example":"取引所AでETHが3,000 USDT、取引所Bで3,018 USDTだとします。両方に資金を置いておき、Aで5 ETH買い、同時にBで5 ETH売ると、差額は18×5＝90 USDTです。ここから両取引所のテイカー手数料0.1%ずつ（約15 USDT＋約15.1 USDT）を引くと、残りは約60 USDTです。さらにAからBへETHを戻すための出金手数料がかかれば、その分も差し引かれます。","mistakes":["取引所間の表示価格の差をそのまま利益だと考え、手数料と送金コストを計算に入れない。","送金中に価格差が消えたり逆転したりする可能性を想定しない。","出金停止中のトークンなど、価格差が開いている理由を確認せずに取引する。"],"faq":[{"q":"アービトラージは本当にノーリスクですか？","a":"理論上は価格差を同時に取りますが、実際には送金遅延、出金停止、スリッページ、取引所の信用リスクなどがあります。ノーリスクではありません。"},{"q":"個人でもアービトラージはできますか？","a":"可能ですが、大きな価格差はすぐに専門業者や自動売買で埋められます。個人の場合は手数料を引いて利益が残るかを慎重に計算する必要があります。"}],"title":"アービトラージ（裁定取引）とは？仕組みと注意点","description":"暗号資産のアービトラージ（裁定取引）の仕組み、取引所間や現物と先物の価格差の取り方、手数料や送金で利益が消える理由を解説します。","related":[["funding-rate-arbitrage","資金調達率アービトラージ（FRアービトラージ）","資金調達率アービトラージとは、現物を買うと同時に同じ数量の無期限先物をショートし、価格変動の影響を打ち消しながら資金調達率の受け取りを狙う取引です。"],["bid-ask-spread","スプレッド（売買価格差）","スプレッドとは、板の最良買い気配（ビッド）と最良売り気配（アスク）の価格差のことで、売買のたびに実質的にかかるコストの一つです。"],["market-maker","マーケットメイカー（MM）","マーケットメイカーとは、買い注文と売り注文の両方を板に出し続けて、他の参加者がいつでも売買できる状態を作る事業者やトレーダーのことです。"],["withdrawal-fee","出金手数料","出金手数料とは、取引所から外部のウォレットや他の取引所へ暗号資産を送るときに差し引かれる手数料で、主にブロックチェーンのネットワーク手数料をまかなうためのものです。"]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"perpetual-futures":{"slug":"perpetual-futures","cat":"derivatives","en":"Perpetual futures (perps)","contentLocale":"ja","term":"無期限先物（パーペチュアル）","aka":["パーペチュアル","無期限先物契約","パーペチュアル先物","perpetual futures"],"short":"無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。","body":[["通常の先物には満期日があり、その日に現物価格へ収束します。無期限先物には満期がないため、代わりに",["資金調達率","funding-rate"],"という仕組みを使います。先物価格が現物価格（",["インデックス価格","index-price"],"）より高いときは",["ロング","long-and-short"],"がショートに、低いときはショートがロングに定期的に支払いを行い、価格の乖離を縮めます。"],"多くの取引所で資金調達率は8時間ごとに精算されますが、取引所や銘柄によっては1時間、2時間、4時間ごとのものもあります。ポジションを長く持つほど支払いや受け取りが積み重なるため、契約仕様のページで精算間隔を確認しておくことが大切です。",[["強制ロスカット","liquidation"],"の判定には、直近の約定価格ではなく",["マーク価格","mark-price"],"が使われるのが一般的です。これにより、一瞬のヒゲによる不当な清算を防いでいます。Binance、OKX、Bybit、Bitgetなどの大手取引所のほか、Hyperliquidのようなオンチェーンの無期限先物DEXもあります。"]],"example":["ETHの無期限先物で、想定元本12,000 USDTのロングを持っているとします。資金調達率が+0.01%で8時間ごとの精算なら、1回あたり12,000×0.0001＝1.2 USDTをショート側に支払います。1日3回で3.6 ",["USDT","usdt"],"、30日続けば108 USDTです。資金調達率が−0.02%に変わると、ロングは逆に1回2.4 USDTを受け取ります。"],"mistakes":["満期がないので放置しても大丈夫だと考え、資金調達率の支払いが積み重なるのを見落とす。","全ての取引所・銘柄で資金調達率の精算が8時間ごとだと思い込む。","画面の最終取引価格だけを見て、強制ロスカットの判定にマーク価格が使われることを知らない。"],"faq":[{"q":"無期限先物と通常の先物の違いは何ですか？","a":"通常の先物には満期日があり、その日に決済されます。無期限先物は満期がなく、資金調達率の支払いで価格を現物に近づけます。"},{"q":"無期限先物を長期間持つとコストはかかりますか？","a":"資金調達率がプラスのときにロングを持つと定期的に支払いが発生します。相場の状況によって受け取る側になることもあり、コストは一定ではありません。"}],"title":"無期限先物（パーペチュアル）とは？仕組みと注意点","description":"無期限先物（パーペチュアル）の仕組み、資金調達率で現物価格に近づく理由、精算間隔やマーク価格の注意点を具体例で解説します。","related":[["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["mark-price","マーク価格","マーク価格とは、先物の含み損益や強制ロスカットの判定に使われる「公正な評価価格」のことで、複数の現物取引所の価格をもとに計算され、一時的な価格操作の影響を受けにくくしています。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"],["futures-contract","先物取引（先物契約）","先物取引とは、ある資産を将来の特定の時点に、あらかじめ決めた価格で売買することを約束する契約で、暗号資産では現物を持たずに価格変動の差額だけをやり取りするのが一般的です。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"現物と先物：買っているものは同じではない"},"coin":null,"tool":"/funding-rates","cta":true},"delivery-futures":{"slug":"delivery-futures","cat":"derivatives","en":"Delivery (quarterly) futures","contentLocale":"ja","term":"限月先物（デリバリー先物・四半期先物）","aka":["デリバリー先物","四半期先物","期限付き先物","クォータリー先物"],"short":"限月先物とは、満期日（決済日）があらかじめ決まっている先物契約で、満期になると自動的に決済され、暗号資産では四半期ごとの契約がよく使われます。","body":[["限月先物には、週次、隔週、四半期などの満期があり、契約名に満期日が入っています。満期日の決済時刻になると、その時点の決済価格（多くは現物イン",["デックス","dex"],"の一定時間の平均）でポジションが自動的に清算されます。",["暗号資産","cryptocurrency"],"の場合、現物の受け渡しではなく差額の受け渡しで決済されるのが一般的です。"],["限月先物には",["資金調達率","funding-rate"],"がありません。その代わり、先物価格と現物価格の差である",["ベーシス","futures-basis"],"が存在し、満期に近づくにつれてこの差は小さくなっていきます。",["強気相場","bull-market"],"では先物が現物より高くなる（コンタンゴ）ことが多く、この差を利用した",["裁定取引","arbitrage"],"も行われます。"],"満期をまたいでポジションを持ちたい場合は、満期前に決済して次の限月で建て直す「ロールオーバー」が必要です。限月先物を提供する取引所や満期のパターン、決済価格の計算方法は取引所ごとに違うため、契約仕様を確認してください。"],"example":"BTCの現物価格が60,000 USDTのとき、3か月後に満期を迎える四半期先物が61,800 USDTで取引されているとします。差であるベーシスは1,800 USDT、約3%です。現物を1 BTC買い、同時に四半期先物を1 BTC分売れば、満期には両者の価格が一致するため、価格の上下に関係なく約1,800 USDT（手数料除く）の差額が確定します。3か月で約3%、単純に年率換算すると約12%です。","mistakes":["満期日を把握しておらず、自動決済されてポジションが消えたことに後から気づく。","限月先物にも無期限先物と同じように資金調達率がかかると思い込む。","異なる限月の契約価格をそのまま比べ、満期までの期間の違いを考えない。"],"faq":[{"q":"限月先物と無期限先物の違いは何ですか？","a":"限月先物には満期日があり、満期に自動決済されます。無期限先物は満期がなく、資金調達率で価格を現物に近づけます。"},{"q":"満期日に何もしないとどうなりますか？","a":"満期の決済価格で自動的にポジションが清算され、損益が確定します。ポジションを継続したい場合は、満期前に次の限月へ乗り換える必要があります。"}],"title":"限月先物（四半期先物）とは？無期限先物との違い","description":"限月先物（デリバリー・四半期先物）の仕組み、満期日の自動決済、ベーシスとロールオーバー、無期限先物との違いを解説します。","related":[["futures-contract","先物取引（先物契約）","先物取引とは、ある資産を将来の特定の時点に、あらかじめ決めた価格で売買することを約束する契約で、暗号資産では現物を持たずに価格変動の差額だけをやり取りするのが一般的です。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["futures-basis","ベーシス（先物と現物の価格差）","ベーシスとは、先物価格と現物価格の差のことで、先物が現物より高い状態をプレミアム（コンタンゴ）、安い状態をディスカウント（バックワーデーション）と呼びます。"],["hedging","ヘッジ（リスクヘッジ）","ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"現物と先物：買っているものは同じではない"},"coin":null,"tool":"/topics/derivatives","cta":false},"initial-margin":{"slug":"initial-margin","cat":"derivatives","en":"Initial margin","contentLocale":"ja","term":"当初証拠金（イニシャルマージン）","aka":["イニシャルマージン","必要証拠金","初期証拠金","initial margin"],"short":"当初証拠金（イニシャルマージン）とは、レバレッジをかけたポジションを新しく建てるときに、最低限差し入れる必要がある証拠金の額のことです。","body":[["当初証拠金は、ポジションの想定元本を",["レバレッジ","leverage"],"倍率で割った額が基本です。10倍なら想定元本の10%、20倍なら5%が必要になります。注文時に残高からこの額が確保され、足りなければ注文は出せません。注文画面に表示される「必要証拠金」や「コスト」がこれにあたります。"],["当初証拠金は、ポジションを維持するのに必要な",["維持証拠金","maintenance-margin"],"よりも多く設定されています。この差が、",["強制ロスカット","liquidation"],"までのクッションになります。当初証拠金を多めに入れる（レバレッジを下げる）ほど、",["清算価格","liquidation-price"],"は建値から遠くなります。"],"多くの取引所では、ポジションの規模が大きくなるほど使える最大レバレッジが下がり、必要な当初証拠金の割合が上がる段階的な仕組みを採用しています。また、手数料分の残高も別に必要になることがあるため、注文前に必要額を確認してください。"],"example":["SOLの",["無期限先物","perpetual-futures"],"で、価格200 USDTのときに150 SOL、想定元本30,000 USDTの",["ロング","long-and-short"],"を15倍で建てるとします。当初証拠金は30,000÷15＝2,000 USDTです。同じポジションを5倍で建てれば6,000 USDTが必要になります。残高が2,500 USDTしかなければ、15倍なら注文できますが、5倍では証拠金不足で注文が通りません。"],"mistakes":["必要な証拠金ぎりぎりの残高で注文し、わずかな値動きで清算に近づく。","当初証拠金と維持証拠金を同じものだと考え、清算までの余裕を誤って計算する。","ポジションが大きくなると最大レバレッジが下がる段階制を知らず、追加注文が通らずに戸惑う。"],"faq":[{"q":"当初証拠金と維持証拠金の違いは何ですか？","a":"当初証拠金はポジションを建てるときに必要な額、維持証拠金はポジションを持ち続けるのに最低限必要な額です。当初証拠金のほうが多く設定されています。"},{"q":"当初証拠金はどう計算しますか？","a":"基本は想定元本をレバレッジ倍率で割った額です。取引所によっては手数料分も必要になります。"}],"title":"当初証拠金（イニシャルマージン）とは？計算方法","description":"当初証拠金（イニシャルマージン）の意味と計算方法、レバレッジとの関係、維持証拠金との違いを先物取引の具体例で解説します。","related":[["maintenance-margin","維持証拠金（メンテナンスマージン）","維持証拠金（メンテナンスマージン）とは、ポジションを持ち続けるために口座に残しておかなければならない最低限の証拠金で、これを下回ると強制ロスカット（清算）が始まります。"],["leverage","レバレッジ","レバレッジとは、差し入れた証拠金の何倍もの金額のポジションを持てる仕組みのことで、利益と損失の両方が倍率に応じて大きくなります。"],["isolated-margin","分離マージン（アイソレーテッドマージン）","分離マージンとは、ポジションごとに証拠金を割り当てて管理する方式で、そのポジションが清算されても失うのは割り当てた証拠金だけに限られます。"],["margin-trading","証拠金取引（マージン取引）","証拠金取引（マージン取引）とは、証拠金を担保として取引所から資金や暗号資産を借り、手持ちの資金より大きな金額で売買する取引方法です。"]],"lesson":{"id":"E20","slug":"maintenance-margin","ep":20,"title":"証拠金がゼロになる前に強制終了されるのはなぜか"},"coin":null,"tool":null,"cta":false},"portfolio-margin":{"slug":"portfolio-margin","cat":"derivatives","en":"Portfolio margin","contentLocale":"ja","term":"ポートフォリオマージン","aka":["ポートフォリオ証拠金","PM","portfolio margin"],"short":"ポートフォリオマージンとは、口座内のすべてのポジションをまとめて評価し、互いに打ち消し合うリスクを考慮して必要な証拠金を計算する方式です。","body":[["通常の証拠金計算では、ポジションごとに",["必要証拠金","initial-margin"],"を足し合わせます。ポートフォリオマージンでは、現物、先物、",["オプション","options"],"をまとめて、価格が上下にいくつかのシナリオで動いたときに口座全体でどれだけ損失が出るかを試算し、その最大損失を基準に証拠金を決めます。"],["例えば、現物でBTCを持ちながら同量の先物ショートを持っていると、価格がどちらに動いても損益がほぼ相殺されます。ポートフォリオマージンでは、このような",["ヘッジ","hedging"],"済みのポジションに必要な証拠金が大きく下がり、資金効率が上がります。反対に、一方向に偏ったポジションでは通常の方式と大きく変わらないか、むしろ厳しくなることもあります。"],["多くの取引所では、一定以上の資産額や取引経験を条件とする上級者向けのモードとして提供されています。計算方式やシナリオの幅、担保として認められる資産は取引所ごとに違います。資金効率が上がるぶん、実質的な",["レバレッジ","leverage"],"が高くなりやすい点に注意が必要です。"]],"example":["現物で2 ",["BTC","bitcoin"],"（BTC価格60,000 ",["USDT","usdt"],"、評価額120,000 USDT）を持ち、同時にBTC無期限先物で2 BTCのショートを持っているとします。通常の計算でショートに10%の証拠金が必要なら12,000 USDTです。ポートフォリオマージンで価格が±15%動くシナリオを試算すると、現物と先物の損益がほぼ打ち消し合うため、必要証拠金は資金調達率や価格差の変動分に相当する数千USDTまで下がることがあります。"],"mistakes":["ポートフォリオマージンならどんなポジションでも証拠金が少なくて済むと誤解する。","ヘッジの片方だけを決済してしまい、必要証拠金が急に増えて清算に近づく。","資金効率が上がった分だけポジションを増やし、実質的なレバレッジを高めすぎる。"],"faq":[{"q":"ポートフォリオマージンは誰でも使えますか？","a":"多くの取引所では、一定以上の資産額や取引条件を満たした利用者向けのモードです。対象や条件は取引所ごとに異なります。"},{"q":"クロスマージンとの違いは何ですか？","a":"クロスマージンは証拠金を共有しますが、必要証拠金はポジションごとに計算します。ポートフォリオマージンは口座全体のリスクをまとめて評価し、ヘッジの効果を証拠金に反映します。"}],"title":"ポートフォリオマージンとは？仕組みとメリット","description":"ポートフォリオマージンの仕組み、ヘッジしたポジションで必要証拠金が下がる理由、クロスマージンとの違いと注意点を解説します。","related":[["cross-margin","クロスマージン","クロスマージンとは、口座内の利用可能な証拠金をすべてのポジションで共有する方式で、清算を遠ざけやすい一方、損失が口座全体に及ぶ可能性があります。"],["isolated-margin","分離マージン（アイソレーテッドマージン）","分離マージンとは、ポジションごとに証拠金を割り当てて管理する方式で、そのポジションが清算されても失うのは割り当てた証拠金だけに限られます。"],["unified-trading-account","統合取引口座（UTA）","統合取引口座（UTA）とは、現物、先物、オプションなどの取引を1つの口座でまとめて行い、口座内の資産全体を証拠金として共有できる取引所の口座形態です。"],["hedging","ヘッジ（リスクヘッジ）","ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。"]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"クロスマージン：なぜ一つの損失が他のポジションに波及するのか"},"coin":null,"tool":null,"cta":false},"short-squeeze":{"slug":"short-squeeze","cat":"derivatives","en":"Short squeeze","contentLocale":"ja","term":"ショートスクイーズ（踏み上げ）","aka":["踏み上げ","ショートスクイズ","short squeeze"],"short":"ショートスクイーズ（踏み上げ）とは、価格の上昇によってショートを持つ人が損切りや強制ロスカットで一斉に買い戻し、その買いがさらに価格を押し上げる現象です。","body":[["ショートを決済するには、買い注文を出す必要があります。ショートが大量に積み上がった状態で価格が上がり始めると、",["損切り","stop-loss"],"の逆指値や清算が次々と発動し、それらがすべて成行の買い注文として市場に出ます。この買いが価格をさらに上げ、次のショートの清算を呼ぶ連鎖が起きます。"],[["暗号資産","cryptocurrency"],"の先物市場では高い",["レバレッジ","leverage"],"が使われるため、ショートスクイーズが短時間で大きな値動きにつながりやすくなります。",["資金調達率","funding-rate"],"が大きくマイナスで、",["建玉","open-interest"],"が高い水準にある状態は、ショートが偏っているサインとして注目されます。反対に",["ロング","long-and-short"],"が一斉に清算される現象はロングスクイーズと呼ばれます。"],"スクイーズによる急騰は、新しい買い手が増えたというより、売り方の買い戻しによる部分が大きいため、清算が出尽くすと勢いが止まることもあります。ショートを持つ場合は、損切りを置き、レバレッジを抑えることが最大の対策です。"],"example":"あるトークンの先物で、1.00 USDT付近に大量のショートが積み上がり、その多くの清算価格が1.10〜1.20 USDTに集中しているとします。好材料で価格が1.10 USDTまで上がると、最初のショートが清算されて成行の買いが入り、1.15 USDTへ。そこでさらに清算が起きて1.25 USDTへと上がり、数分で1.30 USDT、つまり30%上昇します。清算が一巡すると買いが途切れ、1.18 USDTまで戻ることもあります。","mistakes":["ショートが多い銘柄は下がると考え、資金調達率がマイナスでも同じ方向にショートを積み増す。","急騰を見て新しい買い手が来たと考え、スクイーズの最終段階で高値づかみをする。","ショートに損切りを置かず、踏み上げの連鎖で清算される。"],"faq":[{"q":"ショートスクイーズの兆候はありますか？","a":"大きなマイナスの資金調達率、高い建玉、ショートに偏ったロングショート比率などが組み合わさると、起きやすい状態と見られます。ただし必ず起きるわけではありません。"},{"q":"踏み上げとショートスクイーズは同じ意味ですか？","a":"はい、日本語では売り方が買い戻しを強いられて価格が急騰することを「踏み上げ」と呼び、同じ現象を指します。"}],"title":"ショートスクイーズ（踏み上げ）とは？起きる仕組み","description":"ショートスクイーズ（踏み上げ）が起きる仕組み、清算の連鎖、資金調達率や建玉から読む兆候、ショート側の対策を解説します。","related":[["liquidation","強制ロスカット（清算）","強制ロスカット（清算）とは、レバレッジ取引で損失が膨らみ、証拠金が維持証拠金を下回ったときに、取引所がポジションを強制的に決済する仕組みです。"],["short-selling","空売り（ショートセリング）","空売り（ショートセリング）とは、持っていない資産を先に売り、後で値下がりしたところで買い戻して差額を利益にする取引方法です。"],["funding-rate","資金調達率（ファンディングレート）","資金調達率（ファンディングレート）とは、無期限先物の価格を現物価格に近づけるため、ロングとショートの間で定期的にやり取りされる支払いの率のことです。"],["open-interest","建玉（未決済建玉・オープンインタレスト）","建玉（オープンインタレスト）とは、先物やオプションで、まだ決済されずに残っている契約の総数（または総額）のことで、市場にどれだけの資金がポジションとして入っているかを示します。"]],"lesson":null,"coin":null,"tool":"/liquidations","cta":false},"usdc":{"slug":"usdc","cat":"stablecoins","en":"USDC","contentLocale":"ja","term":"USDC（USDコイン）","aka":["USDコイン","USD Coin","USDC"],"short":"USDCとは、米国のCircle社が発行する米ドル連動型のステーブルコインで、現金と米国短期国債などを裏付けに1 USDCが約1ドルになるよう設計されています。","body":[["Circle社は準備資産について、第三者の会計事務所による証明報告を定期的に公表しています。",["イーサリアム","ethereum"],"、ソラナ、Arbitrum、Baseなど多くの",["ブロックチェーン","blockchain"],"でネイティブに発行されており、DeFiでも広く使われています。"],["規制への対応を重視している点が特徴です。EUのMiCAでは",["ステーブルコイン","stablecoin"],"発行者のルールが2024年6月30日から適用され、CircleはMiCAに基づく体制でUSDCを提供しています。日本でも、電子決済手段として国内の登録業者による取り扱いが始まっています。"],["ただしUSDCも、発行体への信頼や裏付け資産の安全性に依存します。2023年3月には、準備金の一部を預けていた米国の銀行の破綻を受けて、一時的に1ドルを大きく下回りました。発行体が特定の",["アドレス","wallet-address"],"を凍結できる点も、USDTと同じです。"]],"example":"あなたがUSDCを5,000 USDC保有していて、市場の混乱で一時的に1 USDCが0.90ドルで取引されたとします。このとき慌てて売れば、受け取るのは4,500ドル分で、500ドルの損失が確定します。その後に価格が1ドル近くに戻れば、売らずに持っていた人は損失を回避できたことになります。ただし、回復するかどうかは裏付け資産の実際の状況次第で、事前には分かりません。","mistakes":["USDCは規制対応しているから、価格が1ドルから外れることはないと考えること。","ネイティブ発行のUSDCと、ブリッジで作られた別のUSDCトークンを混同すること。","DeFiで使うとき、同じ名前の偽USDCトークンのコントラクトを確認しないこと。"],"faq":[{"q":"USDCはどのチェーンで使えますか？","a":"イーサリアム、ソラナ、Arbitrum、Baseなど多くのチェーンでネイティブに発行されています。取引所で入出金する際は、対応ネットワークを必ず確認してください。"},{"q":"USDCは米ドルに交換できますか？","a":"Circle社や対応する取引所を通じて、米ドルなどの法定通貨に換えることができます。利用できる方法や手数料は、国や取引所によって異なります。"}],"title":"USDCとは？Circle発行のステーブルコインの仕組み","description":"USDC（USDコイン）の意味、Circle社による発行と準備資産の仕組み、USDTとの違い、過去のデペッグ事例と注意点を解説します。","related":[["stablecoin","ステーブルコイン","ステーブルコインとは、米ドルなどの法定通貨や他の資産に価格が連動するよう設計された暗号資産で、価格変動を抑えて決済や取引の基軸に使われます。"],["usdt","USDT（テザー）","USDT（テザー）とは、Tether社が発行する米ドル連動型のステーブルコインで、暗号資産取引の基軸通貨として最も広く使われているもののひとつです。"],["depeg","デペッグ（Depeg）","デペッグとは、1ドルなど特定の価値に連動するよう設計されたステーブルコインやトークンの価格が、その目標値から大きく離れてしまう状態のことです。"],["mica","MiCA（EU暗号資産市場規則）","MiCAとは、EU全体で暗号資産の発行者とサービス提供者に共通のルールを定めた規則で、ステーブルコインや取引所などの認可、情報開示、利用者保護を定めています。"]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDTは米ドルですか？なぜ暗号資産を買う時によく見かけるの？"},"coin":{"slug":"usdc","name":"USDC","symbol":"USDC"},"tool":null,"cta":false},"launchpool":{"slug":"launchpool","cat":"exchange-features","en":"Launchpool","contentLocale":"ja","term":"ローンチプール（Launchpool）","aka":["Launchpool","ローンチプール"],"short":"ローンチプールとは、取引所が指定した暗号資産やステーブルコインを一定期間預け入れると、新しく上場するトークンを報酬として受け取れる取引所のキャンペーン型サービスです。","body":[["代表例はBinance Launchpoolで、BitgetやBybitなど他の取引所でも似た仕組みが提供されています。ユーザーはBNBやUSDTなど対象の資産を",["プール","liquidity-pool"],"に預け、その期間中、新規トークンの報酬が預け入れ額のシェアに応じて毎日または毎時配られます。"],["預けた資産は元本として戻ってくるのが一般的で、購入資金を払う",["ローンチパッド","launchpad"],"とは性質が違います。ただし、預けている間は対象資産の価格変動をそのまま受けますし、報酬トークンの価値は",["上場","token-listing"],"後の価格次第で大きく変わります。"],["プールの総額が増えるほど1人あたりの取り分は減るため、表示される年率（",["APR","apr-vs-apy"],"）は刻々と変わります。参加条件（KYCの完了、居住国、1人あたりの上限など）は取引所やプロジェクトごとに異なるので、毎回確認しましょう。"]],"example":["あるプールで、10日間に合計1,000,000枚の新トークンが配られ、預け入れの総額が5億USDTだったとします。あなたが5,000 USDTを預けると、シェアは0.001%で、10日間で受け取れるのは約10枚です。上場後に新トークンが1枚0.5 USDTで取引されれば報酬は約5 ",["USDT","usdt"],"、2 USDTなら約20 USDTになります。期間中に預け入れ総額が10億USDTに増えれば、取り分は約半分に減ります。元本の5,000 USDTは",["ステーブルコイン","stablecoin"],"なので価格変動はほぼありませんが、BNBなどを預けた場合はその値動きも損益に加わります。"],"mistakes":["開始時に表示された年率がそのまま続くと考え、預け入れ総額の増加で利回りが下がることを見落とす。","報酬トークンの価格が上場直後の高値のまま続くと期待して、計算を甘くしてしまう。","対象資産を買うために高値で購入し、その値下がりで報酬以上の損失を出す。"],"faq":[{"q":"ローンチプールで元本が減ることはありますか？","a":"預けた資産の枚数は通常そのまま戻りますが、BNBなど値動きのある資産を預けた場合は、その価格の下落によって円やドル建ての価値が減ることがあります。"},{"q":"ローンチプールとローンチパッドの違いは何ですか？","a":"ローンチプールは資産を預けて報酬として新トークンを受け取る仕組みで、ローンチパッドは資金を払って新トークンを購入する仕組みです。"}],"title":"ローンチプールとは？仕組みと報酬の計算方法","description":"ローンチプール（Launchpool）の意味と仕組み、ローンチパッドとの違い、報酬の計算方法と参加前に確認すべき注意点を解説します。","related":[["launchpad","ローンチパッド（Launchpad）","ローンチパッドとは、取引所などのプラットフォームを通じて、上場前の新しいトークンを決められた価格で購入できるトークンセールの仕組みのことです。"],["staking","ステーキング","ステーキングとは、プルーフ・オブ・ステーク型のブロックチェーンで暗号資産を預け入れてネットワークの運営に参加し、その対価として報酬を受け取る仕組みです。"],["airdrop","エアドロップ","エアドロップとは、プロジェクトが特定の条件を満たしたウォレットやユーザーに、トークンを無料で配布することです。"],["token-listing","上場（トークン上場）","トークン上場とは、取引所が新しい暗号資産の取扱いを開始し、利用者がその取引所で入金・売買・出金できるようにすることです。"]],"lesson":null,"coin":null,"tool":"/activities","cta":true}});
